const parsed = $input.item.json.output[0].content[0].text;

const permitido = {
  segmento: ["VIP", "Estandar", "Descartado"],
  urgencia: ["Alta", "Media", "Baja"],
  intencion: ["Cotizacion", "Soporte", "Info", "Spam"]
};

for (const campo of Object.keys(permitido)) {
  if (!permitido[campo].includes(parsed[campo])) {
    throw new Error(`VALOR_INVALIDO en ${campo}: ${parsed[campo]}`);
  }
}
if (typeof parsed.score !== "number" || parsed.score < 0 || parsed.score > 100) {
  throw new Error("SCORE_INVALIDO: " + parsed.score);
}

return {
  json: {
    ...$('SET_Contexto_Ejecucion').item.json,
    segmento: parsed.segmento,
    urgencia: parsed.urgencia,
    intencion: parsed.intencion,
    score_ia: parsed.score,
    confianza_ia: parsed.confianza,
    resumen_ia: parsed.resumen
  }
};

