const parsed = $input.item.json.output[0].content[0].text;

if (typeof parsed.borrador_respuesta !== "string" || parsed.borrador_respuesta.length < 10) {
  throw new Error("BORRADOR_INVALIDO");
}

return {
  json: {
    ...$('SET_Contexto_Ejecucion').item.json,
    ...$('FN_Validar_JSON_IA').item.json,
    borrador_respuesta: parsed.borrador_respuesta,
    requiere_intervencion_humana: parsed.requiere_intervencion_humana || false
  }
};

const d = $('FN_Validar_Borrador_Mini').item.json;
const cliente = $('AT_Buscar_Cliente').item.json.fields?.Empresa || "Cliente nuevo";
const leadId = $('AT_Crear_Lead').item.json.id;

const blocks = [
  { type: "header", text: { type: "plain_text", text: "🔵 Lead VIP — aprobación requerida" } },
  { type: "section", fields: [
      { type: "mrkdwn", text: `*Empresa:*\n${cliente}` },
      { type: "mrkdwn", text: `*Score IA:*\n${d.score_ia}/100` },
      { type: "mrkdwn", text: `*Urgencia:*\n${d.urgencia}` },
      { type: "mrkdwn", text: `*Segmento:*\n${d.segmento}` }
  ]},
  { type: "section", text: { type: "mrkdwn", text: `*Borrador de respuesta:*\n>${d.borrador_respuesta}` } },
  { type: "actions", elements: [
      { type: "button", style: "primary", text: { type: "plain_text", text: "✅ Aprobar y enviar" },
        value: `${leadId}|approve`, action_id: "approve_lead" },
      { type: "button", text: { type: "plain_text", text: "✏️ Editar" },
        value: `${leadId}|edit`, action_id: "edit_lead" },
      { type: "button", style: "danger", text: { type: "plain_text", text: "❌ Rechazar" },
        value: `${leadId}|reject`, action_id: "reject_lead" }
  ]}
];

return { json: { ...d, slack_blocks: JSON.stringify(blocks), lead_record_id: leadId } };
